import { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  ArrowLeft,
  AlertCircle,
  CheckCircle2,
  CalendarPlus,
  XCircle,
  Save,
} from 'lucide-react';
import { supabase } from '@/integrations/supabase/client';
import { toast } from '@/shared/hooks/use-toast';
import { Button } from '@/shared/ui/button';
import { Badge } from '@/shared/ui/badge';
import { Input } from '@/shared/ui/input';
import { Label } from '@/shared/ui/label';
import { Textarea } from '@/shared/ui/textarea';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/shared/ui/dialog';
import { Alert, AlertDescription, AlertTitle } from '@/shared/ui/alert';
import { MommaPageLayout } from '@/shared/ui/MommaPageLayout';
import { useEmployees } from '../model/useEmployees';
import {
  diasAteData,
  probationAlertLevel,
  probationAlertText,
  validatePrazoExperiencia,
  validateProrrogacao,
} from '../lib/probation';
import type { Contrato, EmployeeListItem, ExperienciaDecisaoTipo } from '../types';

const PROBATION_PILLS: Record<ReturnType<typeof probationAlertLevel>, string> = {
  safe: 'bg-blue-500/10 text-blue-700 dark:text-blue-300 border-blue-500/20',
  d30: 'bg-yellow-500/10 text-yellow-700 dark:text-yellow-300 border-yellow-500/20',
  d15: 'bg-orange-500/10 text-orange-700 dark:text-orange-300 border-orange-500/20',
  d7: 'bg-red-500/10 text-red-700 dark:text-red-300 border-red-500/30',
  overdue: 'bg-red-500/15 text-red-800 dark:text-red-200 border-red-500/40',
};

interface DecisionContext {
  employee: EmployeeListItem;
  contrato: Contrato;
  tipo: ExperienciaDecisaoTipo;
}

export default function ExperienciaPage() {
  const navigate = useNavigate();
  const { employees, loading, fetchEmployees } = useEmployees({ apenas_em_experiencia: true });
  const [decision, setDecision] = useState<DecisionContext | null>(null);

  // Ordenar por dias restantes (mais urgente primeiro)
  const sorted = useMemo(() => {
    return [...employees].sort((a, b) => {
      const da = diasAteData(a.contrato_data_fim) ?? 9999;
      const db = diasAteData(b.contrato_data_fim) ?? 9999;
      return da - db;
    });
  }, [employees]);

  const buckets = useMemo(() => {
    const overdue: EmployeeListItem[] = [];
    const d7: EmployeeListItem[] = [];
    const d15: EmployeeListItem[] = [];
    const d30: EmployeeListItem[] = [];
    const safe: EmployeeListItem[] = [];
    sorted.forEach((e) => {
      const lvl = probationAlertLevel(diasAteData(e.contrato_data_fim));
      if (lvl === 'overdue') overdue.push(e);
      else if (lvl === 'd7') d7.push(e);
      else if (lvl === 'd15') d15.push(e);
      else if (lvl === 'd30') d30.push(e);
      else safe.push(e);
    });
    return { overdue, d7, d15, d30, safe };
  }, [sorted]);

  const openDecision = async (employee: EmployeeListItem, tipo: ExperienciaDecisaoTipo) => {
    // Buscar contrato ativo
    const { data: contratos } = await supabase
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      .from('contratos' as any)
      .select('*')
      .eq('employee_id', employee.id)
      .eq('ativo', true)
      .eq('tipo', 'experiencia')
      .limit(1);
    const contrato = (contratos?.[0] as unknown as Contrato | undefined) ?? null;
    if (!contrato) {
      toast({
        title: 'Contrato não encontrado',
        description: 'Não foi possível encontrar contrato de experiência ativo.',
        variant: 'destructive',
      });
      return;
    }
    setDecision({ employee, contrato, tipo });
  };

  return (
    <MommaPageLayout>
      <div className="relative z-10 w-full max-w-[1400px] mx-auto space-y-8 px-4 sm:px-6 py-6 animate-in fade-in duration-500">
        {/* Header */}
        <div className="flex items-center gap-3 pb-2">
          <Button
            variant="ghost"
            size="icon"
            onClick={() => navigate('/funcionarios')}
            className="rounded-xl hover:bg-[#57715B]/10 shrink-0"
          >
            <ArrowLeft className="h-5 w-5 text-[#57715B] dark:text-[#E6DCCF]" />
          </Button>
          <div className="hidden md:flex h-12 w-12 rounded-2xl bg-amber-500/15 dark:bg-amber-500/10 items-center justify-center shrink-0">
            <AlertCircle className="h-6 w-6 text-amber-700 dark:text-amber-300" />
          </div>
          <div>
            <h1 className="text-3xl md:text-4xl font-bold tracking-tight text-[#2D362E] dark:text-[#E6DCCF] font-serif">
              Período de Experiência
            </h1>
            <p className="text-xs md:text-sm text-[#8C7B6D] dark:text-[#9BA59C] font-medium tracking-widest uppercase opacity-80">
              CLT Art. 445/451 · Decisões pendentes da gerência
            </p>
          </div>
        </div>

        {/* KPIs por urgência */}
        <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
          <UrgencyCard
            label="Vencidos"
            value={buckets.overdue.length}
            color="#C04848"
            description="Decisão atrasada"
            highlight={buckets.overdue.length > 0}
          />
          <UrgencyCard
            label="≤ 7 dias"
            value={buckets.d7.length}
            color="#D9534F"
            description="Crítico"
            highlight={buckets.d7.length > 0}
          />
          <UrgencyCard
            label="≤ 15 dias"
            value={buckets.d15.length}
            color="#E08E45"
            description="Atenção"
          />
          <UrgencyCard
            label="≤ 30 dias"
            value={buckets.d30.length}
            color="#B49364"
            description="Planejar"
          />
          <UrgencyCard
            label="> 30 dias"
            value={buckets.safe.length}
            color="#57715B"
            description="No prazo"
          />
        </div>

        {/* Lista de decisões pendentes */}
        <div className="bg-white/70 dark:bg-zinc-900/70 backdrop-blur-xl border border-[#57715B]/10 dark:border-white/5 rounded-[32px] p-6 shadow-lg shadow-[#57715B]/5">
          {loading ? (
            <div className="py-16 text-center text-[#8C7B6D] dark:text-[#9BA59C]">
              Carregando funcionários em experiência...
            </div>
          ) : sorted.length === 0 ? (
            <div className="py-16 flex flex-col items-center text-center space-y-3">
              <div className="h-14 w-14 rounded-full bg-[#57715B]/10 flex items-center justify-center">
                <CheckCircle2 className="h-7 w-7 text-[#57715B] dark:text-[#8FA893]" />
              </div>
              <p className="font-bold text-[#2D362E] dark:text-[#E6DCCF]">Tudo em dia!</p>
              <p className="text-sm text-[#8C7B6D] dark:text-[#9BA59C] max-w-md">
                Nenhum funcionário em período de experiência no momento.
              </p>
            </div>
          ) : (
            <div className="space-y-3">
              {sorted.map((emp) => {
                const dias = diasAteData(emp.contrato_data_fim);
                const lvl = probationAlertLevel(dias);
                return (
                  <div
                    key={emp.id}
                    className="flex flex-col md:flex-row md:items-center justify-between gap-4 p-4 rounded-2xl border border-[#57715B]/10 dark:border-white/5 hover:bg-[#57715B]/5 dark:hover:bg-[#E6DCCF]/5 transition-all duration-200"
                  >
                    <div className="flex items-center gap-4 flex-1 min-w-0">
                      <div className="h-12 w-12 rounded-2xl bg-[#57715B]/10 dark:bg-[#E6DCCF]/10 flex items-center justify-center shrink-0">
                        <span className="text-sm font-bold text-[#57715B] dark:text-[#E6DCCF]">
                          {emp.nome_completo
                            .split(' ')
                            .map((n) => n[0])
                            .slice(0, 2)
                            .join('')
                            .toUpperCase()}
                        </span>
                      </div>
                      <div className="flex-1 min-w-0">
                        <button
                          onClick={() => navigate(`/funcionarios/${emp.id}`)}
                          className="font-bold text-[#2D362E] dark:text-[#E6DCCF] hover:text-[#57715B] transition-colors text-left truncate w-full"
                        >
                          {emp.nome_completo}
                        </button>
                        <p className="text-xs text-[#8C7B6D] dark:text-[#9BA59C] mt-0.5">
                          {emp.matricula} · {emp.cargo_nome} · {emp.loja_nome}
                        </p>
                      </div>
                      <Badge
                        variant="outline"
                        className={`rounded-full px-3 py-0.5 text-xs whitespace-nowrap ${PROBATION_PILLS[lvl]}`}
                      >
                        {probationAlertText(dias)}
                      </Badge>
                    </div>
                    <div className="flex items-center gap-2 flex-wrap">
                      {(() => {
                        const naSegundaExp = (emp.prorrogacao_count ?? 0) >= 1;
                        return (
                          <>
                            <Button
                              size="sm"
                              onClick={() => openDecision(emp, 'efetivar')}
                              disabled={!naSegundaExp}
                              title={
                                naSegundaExp
                                  ? 'Efetivar como contrato por prazo indeterminado'
                                  : 'Só pode efetivar ao final da 2ª experiência. Prorrogue primeiro.'
                              }
                              className="rounded-xl bg-[#57715B] hover:bg-[#4a6450] text-white shadow-sm disabled:opacity-40 disabled:cursor-not-allowed"
                            >
                              <CheckCircle2 className="h-3.5 w-3.5 mr-1.5" />
                              Efetivar
                            </Button>
                            <Button
                              size="sm"
                              variant="outline"
                              onClick={() => openDecision(emp, 'prorrogar')}
                              disabled={naSegundaExp}
                              title={
                                naSegundaExp
                                  ? 'Já prorrogado uma vez — CLT Art. 451 permite só uma'
                                  : 'Prorrogar para 2ª experiência (CLT Art. 445)'
                              }
                              className="rounded-xl border-[#B49364]/30 text-[#7a5f3a] dark:text-[#C5A065] hover:bg-[#B49364]/10 disabled:opacity-40 disabled:cursor-not-allowed"
                            >
                              <CalendarPlus className="h-3.5 w-3.5 mr-1.5" />
                              Prorrogar
                            </Button>
                          </>
                        );
                      })()}
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => openDecision(emp, 'encerrar')}
                        className="rounded-xl border-red-500/30 text-red-700 dark:text-red-300 hover:bg-red-500/10"
                      >
                        <XCircle className="h-3.5 w-3.5 mr-1.5" />
                        Encerrar
                      </Button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>

      {decision && (
        <DecisionDialog
          context={decision}
          onClose={() => setDecision(null)}
          onSuccess={async () => {
            setDecision(null);
            await fetchEmployees();
          }}
        />
      )}
    </MommaPageLayout>
  );
}

function UrgencyCard({
  label,
  value,
  color,
  description,
  highlight = false,
}: {
  label: string;
  value: number;
  color: string;
  description: string;
  highlight?: boolean;
}) {
  return (
    <div
      className={`bg-white/70 dark:bg-zinc-900/70 backdrop-blur-xl border rounded-[24px] p-4 shadow-sm transition-all ${
        highlight
          ? 'border-red-500/30 shadow-red-500/10'
          : 'border-[#57715B]/10 dark:border-white/5'
      }`}
    >
      <p className="text-xs uppercase tracking-widest font-medium text-[#8C7B6D] dark:text-[#9BA59C] opacity-80">
        {label}
      </p>
      <p className="text-3xl font-bold mt-1.5 font-serif" style={{ color }}>
        {value}
      </p>
      <p className="text-xs text-[#8C7B6D]/70 dark:text-[#9BA59C]/70 mt-0.5">{description}</p>
    </div>
  );
}

function DecisionDialog({
  context,
  onClose,
  onSuccess,
}: {
  context: DecisionContext;
  onClose: () => void;
  onSuccess: () => void;
}) {
  const { employee, contrato, tipo } = context;
  const [justificativa, setJustificativa] = useState('');
  const [novaDataFim, setNovaDataFim] = useState('');
  const [submitting, setSubmitting] = useState(false);

  // Validações específicas
  const prorrogacaoCheck = useMemo(() => {
    if (tipo !== 'prorrogar') return { valid: true };
    return validateProrrogacao(contrato);
  }, [tipo, contrato]);

  const novaDataCheck = useMemo(() => {
    if (tipo !== 'prorrogar' || !novaDataFim) return { valid: false, dias: 0 };
    return validatePrazoExperiencia(contrato.data_inicio, novaDataFim);
  }, [tipo, novaDataFim, contrato.data_inicio]);

  const justificativaObrigatoria = tipo !== 'efetivar';
  const formValido =
    prorrogacaoCheck.valid &&
    (tipo !== 'prorrogar' || (novaDataFim && novaDataCheck.valid)) &&
    (!justificativaObrigatoria || justificativa.trim().length > 0);

  // Valor inicial sugerido para nova data fim (30 dias depois do fim da 1ª, contando o próprio dia do fim)
  useEffect(() => {
    if (tipo === 'prorrogar' && contrato.data_fim_inicial && !novaDataFim) {
      const sugerido = new Date(contrato.data_fim_inicial + 'T00:00:00');
      sugerido.setDate(sugerido.getDate() + 30);
      // Mas não pode passar de 90 dias do início
      const maxFim = new Date(contrato.data_inicio + 'T00:00:00');
      maxFim.setDate(maxFim.getDate() + 90);
      const final = sugerido > maxFim ? maxFim : sugerido;
      setNovaDataFim(final.toISOString().slice(0, 10));
    }
  }, [tipo, contrato, novaDataFim]);

  const handleSubmit = async () => {
    if (!formValido) return;
    setSubmitting(true);
    try {
      // 1) Insere registro em experiencia_decisoes
      const { error: errDecisao } = await supabase
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        .from('experiencia_decisoes' as any)
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        .insert({
          contrato_id: contrato.id,
          employee_id: employee.id,
          tipo,
          decidido_por: (await supabase.auth.getUser()).data.user?.id,
          justificativa: justificativa.trim() || null,
          metadata: tipo === 'prorrogar' ? { nova_data_fim: novaDataFim } : null,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        } as any);
      if (errDecisao) throw errDecisao;

      // 2) Atualiza contrato + employee conforme decisão
      if (tipo === 'efetivar') {
        await supabase
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          .from('contratos' as any)
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          .update({ ativo: false } as any)
          .eq('id', contrato.id);
        await supabase
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          .from('contratos' as any)
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          .insert({
            employee_id: employee.id,
            tipo: 'indeterminado',
            data_inicio: new Date().toISOString().slice(0, 10),
            ativo: true,
          } as any);
        await supabase
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          .from('employees' as any)
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          .update({ status: 'active' } as any)
          .eq('id', employee.id);
      } else if (tipo === 'prorrogar') {
        await supabase
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          .from('contratos' as any)
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          .update({
            data_fim_prorrogado: novaDataFim,
            prorrogacao_count: (contrato.prorrogacao_count ?? 0) + 1,
          } as any)
          .eq('id', contrato.id);
      } else if (tipo === 'encerrar') {
        const hoje = new Date().toISOString().slice(0, 10);
        await supabase
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          .from('contratos' as any)
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          .update({ ativo: false } as any)
          .eq('id', contrato.id);
        await supabase
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          .from('employees' as any)
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          .update({
            status: 'terminated',
            data_demissao: hoje,
            motivo_demissao: justificativa.trim(),
          } as any)
          .eq('id', employee.id);
      }

      toast({
        title:
          tipo === 'efetivar'
            ? 'Funcionário efetivado'
            : tipo === 'prorrogar'
            ? 'Experiência prorrogada'
            : 'Contrato encerrado',
        description: employee.nome_completo,
      });
      onSuccess();
    } catch (err) {
      // eslint-disable-next-line no-console
      console.error('[DecisionDialog] erro', err);
      toast({
        title: 'Erro ao registrar decisão',
        description: err instanceof Error ? err.message : 'Erro desconhecido',
        variant: 'destructive',
      });
    } finally {
      setSubmitting(false);
    }
  };

  const dias = diasAteData(
    contrato.data_fim_prorrogado ?? contrato.data_fim_inicial,
  );

  // Cálculos das duas experiências
  const hoje = new Date();
  hoje.setHours(0, 0, 0, 0);
  const fimInicialDate = contrato.data_fim_inicial
    ? new Date(contrato.data_fim_inicial + 'T00:00:00')
    : null;
  const primeiraConcluida = !!(fimInicialDate && hoje > fimInicialDate);
  const diasPrimeiraTotal = fimInicialDate
    ? Math.round(
        (fimInicialDate.getTime() - new Date(contrato.data_inicio + 'T00:00:00').getTime()) /
          (1000 * 60 * 60 * 24),
      )
    : null;
  const diasRestantesPrimeira = diasAteData(contrato.data_fim_inicial);

  // Segunda experiência: já existe (data_fim_prorrogado) OU vai ser definida agora
  const temProrrogacao = !!contrato.data_fim_prorrogado;
  // Início da 2ª = mesmo dia do fim da 1ª (prorrogação conta a partir do fim, não do dia seguinte)
  const inicio2a = contrato.data_fim_inicial ?? null;

  return (
    <Dialog open={true} onOpenChange={(o) => !o && onClose()}>
      <DialogContent className="max-w-2xl bg-white/95 dark:bg-zinc-900/95 backdrop-blur-xl border-[#57715B]/10 dark:border-white/10 rounded-3xl">
        <DialogHeader>
          <DialogTitle className="text-2xl font-serif text-[#2D362E] dark:text-[#E6DCCF] capitalize">
            {tipo === 'efetivar'
              ? 'Efetivar funcionário'
              : tipo === 'prorrogar'
              ? 'Prorrogar experiência'
              : 'Encerrar contrato'}
          </DialogTitle>
          <DialogDescription className="text-[#8C7B6D] dark:text-[#9BA59C]">
            {employee.nome_completo} · {employee.cargo_nome} · {employee.loja_nome}
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* Card das DUAS experiências lado-a-lado */}
          <div className="bg-[#57715B]/5 dark:bg-white/5 rounded-2xl p-4 text-sm">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {/* 1ª Experiência */}
              <div className="space-y-2 md:pr-4 md:border-r md:border-[#57715B]/15">
                <div className="flex items-center justify-between">
                  <span className="text-[10px] uppercase tracking-widest font-bold text-[#57715B] dark:text-[#8FA893]">
                    1ª Experiência
                  </span>
                  <Badge
                    variant="outline"
                    className={`rounded-full text-[10px] px-2 py-0 ${
                      primeiraConcluida
                        ? 'bg-[#33733F]/10 text-[#33733F] border-[#33733F]/20'
                        : 'bg-blue-500/10 text-blue-700 border-blue-500/20'
                    }`}
                  >
                    {primeiraConcluida ? '✓ Concluída' : 'Em andamento'}
                  </Badge>
                </div>
                <div className="space-y-1">
                  <div className="flex items-baseline justify-between">
                    <span className="text-[10px] uppercase tracking-widest text-[#8C7B6D]">Início</span>
                    <span className="text-sm font-mono text-[#2D362E] dark:text-[#E6DCCF]">
                      {formatDate(contrato.data_inicio)}
                    </span>
                  </div>
                  <div className="flex items-baseline justify-between">
                    <span className="text-[10px] uppercase tracking-widest text-[#8C7B6D]">Fim</span>
                    <span className="text-sm font-mono text-[#2D362E] dark:text-[#E6DCCF]">
                      {formatDate(contrato.data_fim_inicial)}
                    </span>
                  </div>
                  <div className="flex items-baseline justify-between pt-1 border-t border-[#57715B]/10">
                    <span className="text-[10px] uppercase tracking-widest text-[#8C7B6D]">
                      {primeiraConcluida ? 'Duração' : 'Restam'}
                    </span>
                    <span className="text-sm font-mono font-bold text-[#57715B] dark:text-[#8FA893]">
                      {primeiraConcluida
                        ? diasPrimeiraTotal !== null
                          ? `${diasPrimeiraTotal}d`
                          : '—'
                        : diasRestantesPrimeira !== null
                        ? `${diasRestantesPrimeira}d`
                        : '—'}
                    </span>
                  </div>
                </div>
              </div>

              {/* 2ª Experiência (prorrogação) */}
              <div className="space-y-2 md:pl-2">
                <div className="flex items-center justify-between">
                  <span className="text-[10px] uppercase tracking-widest font-bold text-[#7a5f3a] dark:text-[#C5A065]">
                    2ª Experiência · Prorrogação
                  </span>
                  {temProrrogacao ? (
                    <Badge
                      variant="outline"
                      className="rounded-full text-[10px] px-2 py-0 bg-[#B49364]/10 text-[#7a5f3a] dark:text-[#C5A065] border-[#B49364]/30"
                    >
                      Configurada
                    </Badge>
                  ) : tipo === 'prorrogar' && prorrogacaoCheck.valid ? (
                    <Badge
                      variant="outline"
                      className="rounded-full text-[10px] px-2 py-0 bg-blue-500/10 text-blue-700 border-blue-500/20"
                    >
                      Definir agora ↓
                    </Badge>
                  ) : (
                    <Badge
                      variant="outline"
                      className="rounded-full text-[10px] px-2 py-0 bg-zinc-500/10 text-zinc-600 border-zinc-500/20"
                    >
                      Não definida
                    </Badge>
                  )}
                </div>

                {temProrrogacao ? (
                  <div className="space-y-1">
                    <div className="flex items-baseline justify-between">
                      <span className="text-[10px] uppercase tracking-widest text-[#8C7B6D]">Início</span>
                      <span className="text-sm font-mono text-[#2D362E] dark:text-[#E6DCCF]">
                        {inicio2a ? formatDate(inicio2a) : '—'}
                      </span>
                    </div>
                    <div className="flex items-baseline justify-between">
                      <span className="text-[10px] uppercase tracking-widest text-[#8C7B6D]">Fim</span>
                      <span className="text-sm font-mono text-[#2D362E] dark:text-[#E6DCCF]">
                        {formatDate(contrato.data_fim_prorrogado)}
                      </span>
                    </div>
                    <div className="flex items-baseline justify-between pt-1 border-t border-[#B49364]/15">
                      <span className="text-[10px] uppercase tracking-widest text-[#8C7B6D]">
                        Restam
                      </span>
                      <span className="text-sm font-mono font-bold text-[#7a5f3a] dark:text-[#C5A065]">
                        {dias === null ? '—' : `${dias}d`}
                      </span>
                    </div>
                  </div>
                ) : tipo === 'prorrogar' && prorrogacaoCheck.valid ? (
                  <div className="space-y-2">
                    <div className="flex items-baseline justify-between">
                      <span className="text-[10px] uppercase tracking-widest text-[#8C7B6D]">Início</span>
                      <span className="text-sm font-mono text-[#2D362E] dark:text-[#E6DCCF]">
                        {inicio2a ? formatDate(inicio2a) : '—'}
                      </span>
                    </div>
                    <div>
                      <Label className="text-[10px] uppercase tracking-widest text-[#8C7B6D]">
                        Nova data de fim *
                      </Label>
                      <Input data-mia-field="nova_data_fim"
                        type="date"
                        value={novaDataFim}
                        min={inicio2a ?? undefined}
                        onChange={(e) => setNovaDataFim(e.target.value)}
                        className="bg-white/60 dark:bg-zinc-900/60 border-[#B49364]/30 dark:border-white/10 rounded-xl h-9 mt-1"
                      />
                      {novaDataFim && !novaDataCheck.valid && (
                        <p className="text-[11px] text-red-600 mt-1">{novaDataCheck.error}</p>
                      )}
                      {novaDataFim && novaDataCheck.valid && (
                        <p className="text-[11px] text-[#33733F] dark:text-[#8FA893]">
                          ✓ {novaDataCheck.dias}d totais (CLT Art. 445 ≤ 90)
                        </p>
                      )}
                    </div>
                  </div>
                ) : (
                  <div className="py-2 text-xs italic text-[#8C7B6D] dark:text-[#9BA59C]">
                    Prorrogação não configurada.
                    {!prorrogacaoCheck.valid && contrato.prorrogacao_count >= 1 && (
                      <span className="block mt-1 text-[10px] not-italic text-red-600">
                        Já prorrogado uma vez — CLT permite só uma.
                      </span>
                    )}
                  </div>
                )}
              </div>
            </div>
          </div>

          {tipo === 'prorrogar' && !prorrogacaoCheck.valid && (
            <Alert
              variant="destructive"
              className="rounded-2xl bg-red-500/10 border-red-500/30 text-red-700 dark:text-red-300"
            >
              <AlertCircle className="h-4 w-4" />
              <AlertTitle>Prorrogação bloqueada</AlertTitle>
              <AlertDescription>{prorrogacaoCheck.error}</AlertDescription>
            </Alert>
          )}

          {tipo === 'efetivar' && (
            <Alert className="rounded-2xl bg-[#57715B]/10 border-[#57715B]/30 text-[#2D362E] dark:text-[#E6DCCF]">
              <CheckCircle2 className="h-4 w-4 text-[#57715B]" />
              <AlertTitle>Efetivação CLT</AlertTitle>
              <AlertDescription>
                O contrato de experiência será encerrado e substituído por contrato por prazo
                indeterminado. Status do funcionário muda para "Ativo".
              </AlertDescription>
            </Alert>
          )}

          {tipo === 'encerrar' && (
            <Alert
              variant="destructive"
              className="rounded-2xl bg-red-500/10 border-red-500/30 text-red-700 dark:text-red-300"
            >
              <XCircle className="h-4 w-4" />
              <AlertTitle>Rescisão</AlertTitle>
              <AlertDescription>
                Esta ação encerra o contrato e marca o funcionário como desligado. Em seguida,
                gere o evento eSocial S-2299 (até 10 dias do desligamento).
              </AlertDescription>
            </Alert>
          )}

          <div className="space-y-2">
            <Label className="text-xs uppercase tracking-widest font-medium text-[#8C7B6D] dark:text-[#9BA59C]">
              Justificativa {justificativaObrigatoria ? '*' : '(opcional)'}
            </Label>
            <Textarea data-mia-field="justificativa"
              value={justificativa}
              onChange={(e) => setJustificativa(e.target.value)}
              placeholder={
                tipo === 'efetivar'
                  ? 'Observações sobre a efetivação (opcional)'
                  : 'Motivo da decisão'
              }
              rows={3}
              className="bg-white/60 dark:bg-zinc-900/60 border-[#57715B]/20 dark:border-white/10 rounded-2xl"
            />
          </div>
        </div>

        <DialogFooter>
          <Button data-mia-action="on-close"
            variant="outline"
            onClick={onClose}
            disabled={submitting}
            className="rounded-2xl border-[#57715B]/20 text-[#57715B] dark:text-[#E6DCCF] hover:bg-[#57715B]/10"
          >
            Cancelar
          </Button>
          <Button data-mia-action="submit"
            onClick={handleSubmit}
            disabled={!formValido || submitting}
            className={`rounded-2xl text-white shadow-md ${
              tipo === 'encerrar'
                ? 'bg-red-600 hover:bg-red-700 shadow-red-500/20'
                : 'bg-[#57715B] hover:bg-[#4a6450] shadow-[#57715B]/20'
            }`}
          >
            <Save className="h-4 w-4 mr-2" />
            {submitting ? 'Registrando...' : 'Confirmar decisão'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

function formatDate(d?: string | null) {
  if (!d) return null;
  return new Date(d + (d.includes('T') ? '' : 'T00:00:00')).toLocaleDateString('pt-BR');
}

